import backtrader as bt


class MultiTimeframeCandlestickAggregationStrategy(bt.Strategy):
    params = (
        ('timeframes', (120, 60, 30, 15)),
        ('pattern', 'bullish_engulfing'),
        ('risk_per_trade', 0.01),
        ('atr_period', 14),
        ('profit_atr_multiple', 1.5),
        ('stop_atr_multiple', 0.5),
    )

    def __init__(self):
        self.atr = bt.indicators.ATR(self.data, period=self.p.atr_period)
        self.order = None
        self.stop_order = None
        self.target_order = None
        self.entry_atr = None
        self.entry_timeframe = None
        self._active = {minutes: None for minutes in self.p.timeframes}
        self._completed = {minutes: [] for minutes in self.p.timeframes}
        self.pattern_counts = []

    @staticmethod
    def bullish_engulfing(previous, current):
        return (previous['close'] < previous['open'] and
                current['close'] > current['open'] and
                current['open'] <= previous['close'] and
                current['close'] >= previous['open'])

    @staticmethod
    def bearish_engulfing(previous, current):
        return (previous['close'] > previous['open'] and
                current['close'] < current['open'] and
                current['open'] >= previous['close'] and
                current['close'] <= previous['open'])

    def _matches(self, previous, current, opposite=False):
        pattern = self.p.pattern
        if callable(pattern):
            if opposite:
                opposite_pattern = getattr(pattern, 'opposite', None)
                if opposite_pattern is None:
                    return self.bearish_engulfing(previous, current)
                return bool(opposite_pattern(previous, current))
            return bool(pattern(previous, current))
        if pattern == 'bullish_engulfing':
            matcher = self.bearish_engulfing if opposite else self.bullish_engulfing
            return matcher(previous, current)
        matcher = getattr(self, pattern)
        if opposite:
            opposite_matcher = getattr(self, 'opposite_' + pattern)
            return bool(opposite_matcher(previous, current))
        return bool(matcher(previous, current))

    def _bucket(self, timestamp, minutes):
        session_open_minutes = 9 * 60 + 30
        elapsed = timestamp.hour * 60 + timestamp.minute - session_open_minutes
        index = elapsed // minutes
        start_total = session_open_minutes + index * minutes
        start = timestamp.replace(hour=start_total // 60,
                                  minute=start_total % 60,
                                  second=0, microsecond=0)
        key = timestamp.toordinal() * 24 * 60 + start_total
        return start, key

    def _finish(self, minutes):
        candle = self._active[minutes]
        if candle is None:
            return
        completed = self._completed[minutes]
        candle['pattern'] = (len(completed) > 0 and
                             self._matches(completed[-1], candle))
        candle['opposite'] = (len(completed) > 0 and
                              self._matches(completed[-1], candle, opposite=True))
        completed.append(candle)

    def _update_candles(self):
        timestamp = self.data.datetime.datetime(0)
        finished = []
        for minutes in self.p.timeframes:
            start, key = self._bucket(timestamp, minutes)
            current = self._active[minutes]
            if current is None or current['start'] != start:
                if current is not None:
                    self._finish(minutes)
                    finished.append(minutes)
                self._active[minutes] = {
                    'start': start,
                    'start_key': key,
                    'end_key': key + minutes,
                    'open': float(self.data.open[0]),
                    'high': float(self.data.high[0]),
                    'low': float(self.data.low[0]),
                    'close': float(self.data.close[0]),
                }
            else:
                current['high'] = max(current['high'], float(self.data.high[0]))
                current['low'] = min(current['low'], float(self.data.low[0]))
                current['close'] = float(self.data.close[0])
        return finished

    def _patterns_inside(self, minutes, parent):
        return [candle for candle in self._completed[minutes]
                if candle['start_key'] >= parent['start_key'] and
                candle['end_key'] <= parent['end_key'] and candle['pattern']]

    def _drill_down(self):
        highest = self.p.timeframes[0]
        if not self._completed[highest]:
            return False
        parent = self._completed[highest][-1]
        if not parent['pattern']:
            return False

        counts = {highest: 1}
        for minutes in self.p.timeframes[1:]:
            counts[minutes] = len(self._patterns_inside(minutes, parent))
        self.pattern_counts.append({
            'window_start': parent['start'],
            'window_end_key': parent['end_key'],
            'counts': dict(counts),
        })

        increased = False
        entry_timeframe = self.p.timeframes[1]
        best_count = counts[entry_timeframe]
        for higher, lower in zip(self.p.timeframes, self.p.timeframes[1:]):
            if counts[lower] > counts[higher]:
                increased = True
            if counts[lower] > best_count:
                best_count = counts[lower]
                entry_timeframe = lower
        if increased:
            self.entry_timeframe = entry_timeframe
        return increased

    def _cancel_protective_orders(self):
        if self.stop_order is not None:
            self.cancel(self.stop_order)
        if self.target_order is not None:
            self.cancel(self.target_order)

    def next(self):
        finished = self._update_candles()

        if self.position:
            if (self.entry_timeframe in finished and
                    self._completed[self.entry_timeframe][-1]['opposite'] and
                    self.order is None):
                self._cancel_protective_orders()
                self.order = self.close()
            return

        if self.order is not None:
            return
        if self.p.timeframes[0] in finished and self._drill_down():
            atr = float(self.atr[0])
            if atr > 0.0:
                self.entry_atr = atr
                risk_cash = self.broker.getvalue() * self.p.risk_per_trade
                size = risk_cash / (self.p.stop_atr_multiple * atr)
                self.order = self.buy(size=size)

    def notify_order(self, order):
        if order.status == order.Completed:
            if order.isbuy():
                stop_price = order.executed.price - self.p.stop_atr_multiple * self.entry_atr
                target_price = order.executed.price + self.p.profit_atr_multiple * self.entry_atr
                self.stop_order = self.sell(size=order.executed.size,
                                            exectype=bt.Order.Stop,
                                            price=stop_price)
                self.target_order = self.sell(size=order.executed.size,
                                              exectype=bt.Order.Limit,
                                              price=target_price,
                                              oco=self.stop_order)
            elif order is self.stop_order or order is self.target_order:
                self.entry_atr = None
                self.entry_timeframe = None
        if order.status in (order.Completed, order.Canceled,
                            order.Margin, order.Rejected):
            if order is self.order:
                self.order = None
            if order is self.stop_order:
                self.stop_order = None
            if order is self.target_order:
                self.target_order = None

    def get_analysis(self):
        return list(self.pattern_counts)
